package com.example.proxy;

import java.lang.reflect.Proxy;

public class JdkProxyDemo {

    interface PayService {
        String pay(long amount);
    }

    static class AlipayService implements PayService {
        public String pay(long amount) {
            return "支付宝支付 " + amount + " 元";
        }
    }

    public static void main(String[] args) {
        PayService target = new AlipayService();

        PayService proxy = (PayService) Proxy.newProxyInstance(
            target.getClass().getClassLoader(),
            new Class<?>[] { PayService.class },
            (p, method, mArgs) -> {
                System.out.println("[前置] 记录支付请求");
                Object result = method.invoke(target, mArgs);
                System.out.println("[后置] 记录支付结果");
                return result;
            });

        System.out.println(proxy.pay(100));
        System.out.println("代理类型: " + proxy.getClass().getName());
        // 代理类型形如 com.sun.proxy.$Proxy0，与 AlipayService 是两个对象
    }
}

package com.example.proxy;

import org.springframework.cglib.proxy.Enhancer;
import org.springframework.cglib.proxy.MethodInterceptor;

public class CglibBoundaryDemo {

    static class Greeter {
        public String hello(String name) {
            return "你好, " + name;
        }

        public final String bye(String name) {
            return "再见, " + name;
        }

        private String secret() {
            return "内部密语";
        }
    }

    public static void main(String[] args) {
        Enhancer enhancer = new Enhancer();
        enhancer.setSuperclass(Greeter.class);
        enhancer.setCallback((MethodInterceptor) (obj, method, mArgs, proxy) -> {
            System.out.println("[拦截到] " + method.getName());
            return proxy.invokeSuper(obj, mArgs);
        });

        Greeter greeter = (Greeter) enhancer.create();
        System.out.println(greeter.hello("张三"));
        System.out.println(greeter.bye("张三"));

        greeter.secret();
        // 输出：只有 hello 被拦截。
        // bye 是 final 无法被覆写（CGLIB 直接跳过），secret 是 private 根本不可见。
    }
}
